DISK=/dev/sda; HOST=archvm; USERN=user; PASS=changeme; TZ=Europe/Warsaw; timedatectl set-ntp true && wipefs -af $DISK && parted -s $DISK mklabel gpt mkpart ESP fat32 1MiB 1GiB set 1 esp on mkpart root ext4 1GiB 100% && sleep 2 && mkfs.fat -F32 ${DISK}1 && mkfs.ext4 -F ${DISK}2 && mount ${DISK}2 /mnt && mount --mkdir ${DISK}1 /mnt/boot && pacstrap -K /mnt base linux linux-firmware grub efibootmgr networkmanager sudo nano && genfstab -U /mnt > /mnt/etc/fstab && arch-chroot /mnt /bin/bash -c "ln -sf /usr/share/zoneinfo/$TZ /etc/localtime; hwclock --systohc; sed -i 's/^#en_US.UTF-8/en_US.UTF-8/' /etc/locale.gen; locale-gen; echo LANG=en_US.UTF-8 > /etc/locale.conf; echo $HOST > /etc/hostname; grub-install --target=x86_64-efi --efi-directory=/boot --bootloader-id=GRUB --removable; grub-mkconfig -o /boot/grub/grub.cfg; systemctl enable NetworkManager; useradd -m -G wheel $USERN; echo $USERN:$PASS | chpasswd; echo root:$PASS | chpasswd; sed -i 's/^# %wheel ALL=(ALL:ALL) ALL/%wheel ALL=(ALL:ALL) ALL/' /etc/sudoers" && umount -R /mnt && echo "Done. Remove the ISO and reboot."
